import{_ as a,c as i,o as n,ah as t,aj as o}from"./chunks/framework.CDL6_Pj-.js";const p=JSON.parse('{"title":"Join the Challenge","description":"","frontmatter":{"title":"Join the Challenge"},"headers":[],"relativePath":"join-the-challenge.md","filePath":"join-the-challenge.md"}'),r={name:"join-the-challenge.md"};function l(s,e,d,h,g,c){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="join-the-challenge" tabindex="-1">Join The Challenge! <a class="header-anchor" href="#join-the-challenge" aria-label="Permalink to “Join The Challenge!”">​</a></h1><h2 id="join-the-challenge-1" tabindex="-1">Join the challenge! <a class="header-anchor" href="#join-the-challenge-1" aria-label="Permalink to “Join the challenge!”">​</a></h2><ol><li>Sign up and apply to join the challenge on the <a href="https://www.synapse.org/Synapse:syn72060672/wiki/636549" target="_blank" rel="noreferrer">Synapse website</a>.</li><li>Submit your team information <a href="https://www.wjx.top/vm/Yf5nmWW.aspx#" target="_blank" rel="noreferrer">here</a>.</li></ol><ul><li><blockquote><p>After clicking the Submit button, the password for extracting the data will be displayed upon submission, as shown in the figure on the right. Please save it carefully.</p></blockquote></li></ul><h3 id="download-the-data" tabindex="-1">Download the data <a class="header-anchor" href="#download-the-data" aria-label="Permalink to “Download the data”">​</a></h3><ul><li><strong>Full challenge data:</strong> <a href="https://www.synapse.org/Synapse:syn72060672/wiki/639758" target="_blank" rel="noreferrer">Download here</a></li></ul><h3 id="train-the-model" tabindex="-1">Train the model <a class="header-anchor" href="#train-the-model" aria-label="Permalink to “Train the model”">​</a></h3><p>Participants are expected to train models in their local computational environments and submit docker containers on the Synapse platform.<br> A leaderboard will be maintained on the Synapse platform during the validation phase.</p><h2 id="code-availability" tabindex="-1">Code Availability <a class="header-anchor" href="#code-availability" aria-label="Permalink to “Code Availability”">​</a></h2><p>We provide the code to facilitate participation in the <strong>MRIxFields2026</strong> challenge at <a href="https://github.com/mrixfields" target="_blank" rel="noreferrer">GitHub</a>.</p><p>A brief description of the provided package is as follows:</p><ul><li><strong>Baseline/</strong>: Contains baseline models (<strong>CUT, CycleGAN, and StarGAN v2</strong>), training and inference scripts, and configuration files for all three tasks.</li><li><strong>Tutorial/</strong>: Jupyter notebooks for data exploration, preprocessing pipeline demonstration, and baseline training walkthrough.</li><li><strong>Evaluation/</strong>: Standalone evaluation code for computing all five metrics (<strong>nRMSE, SSIM, LPIPS, Dice, and Volume Consistency</strong>) as well as <strong>SynthSeg</strong>-based brain segmentation.</li><li><strong>Submission/</strong>: Docker submission template, output format specification, and hardware requirements.</li></ul><h2 id="evaluation-platform" tabindex="-1">Evaluation platform <a class="header-anchor" href="#evaluation-platform" aria-label="Permalink to “Evaluation platform”">​</a></h2><p>Evaluation of the received docker (test phase) will be performed on a cloud server with a configuration as follows:</p><ul><li><strong>OS:</strong> Linux (RockyOS 9)</li><li><strong>CPU:</strong> 2.0GHz, 112 cores</li><li><strong>RAM:</strong> 64 GB</li><li><strong>GPU:</strong> A6000 (48 GB VRAM, single GPU)</li><li><strong>GPU Driver Version:</strong> 575</li><li><strong>CUDA Version:</strong> 12.9</li><li><strong>Time Limitation:</strong> 1 hours/team for each task</li></ul><h2 id="publication-references" tabindex="-1">Publication References <a class="header-anchor" href="#publication-references" aria-label="Permalink to “Publication References”">​</a></h2><p>You are free to use and/or refer to the MRIxFields2026 challenge and datasets in your own research after the embargo period (Dec. 2026), provided that you cite the following manuscripts:</p><p><strong>Reference from the organizers</strong></p><ol><li>Dai, Y. et al. Leveraging Deep Learning to Enhance MRI for Brain Disorders. Preprint at: <a href="https://doi.org/10.1101/2025.02.10.25321126" target="_blank" rel="noreferrer">https://doi.org/10.1101/2025.02.10.25321126</a> (2025).</li><li>Dai, Y., Wang, C. &amp; Wang, H. Deep compressed sensing MRI via a gradient-enhanced fusion model. Med Phys 50, 1390–1405 (2023).</li><li>Wang, F. et al. Multiple B-Value Model-Based Residual Network (MORN) for Accelerated High-Resolution Diffusion-Weighted Imaging. IEEE J Biomed Health Inform 26, 4575–4586 (2022).</li><li>Wang, C. et al. Protocol for Brain Magnetic Resonance Imaging and Extraction of Imaging-Derived Phenotypes from the China Phenobank Project. Phenomics 3, 642–656 (2023).</li><li>Tang, W. et al. Aleatoric-Uncertainty-Aware Maximum Intensity Projection-Based GAN for 7T-Like Generation From 3T TOF-MRA. IEEE J Biomed Health Inform 29, 6664–6677 (2025).</li><li>Lee, P. K., Qiu, Y., Wang, C. &amp; Zhang, Z. Multiband Fast Spin Echo on portable low-field systems. Magn Reson Med 95, 188–203 (2026).</li><li>Lee, P. K., Qiu, Y., Chen, S., Wang, C. &amp; Zhang, Z. Diffusion Weighted Fast Spin Echo With RF-Encoded Slabs for Portable Low-Field MRI Systems. Magn Reson Med (2026). <a href="https://doi.org/10.1002/mrm.70292" target="_blank" rel="noreferrer">https://doi.org/10.1002/mrm.70292</a></li><li>Qiu, Y., Dai, K., Zhong, S. et al. Spatiotemporal encoding MRI in a portable low-field system. Magn Reson Med 92, 1011–1021 (2024).</li><li>Wang, Y., Xiong, H., Sun, K., Bai, S., Dai, L., Ding, Z., Liu, J., Wang, Q., Liu, Q. &amp; Shen, D. Towards general text-guided multimodal brain MRI synthesis for diagnosis and medical image analysis. Cell Rep Med (2025).</li></ol><p><strong>References from others</strong></p><ol><li>Obusez, E. C. et al. 7T MR of intracranial pathology: Preliminary observations and comparisons to 3T and 1.5T. Neuroimage 168, 459–476 (2018).</li><li>Maranzano, J. et al. Comparison of Multiple Sclerosis Cortical Lesion Types Detected by Multicontrast 3T and 7T MRI. AJNR Am J Neuroradiol 40, 1162–1169 (2019).</li><li>Cosottini, M. et al. Comparison of 3T and 7T susceptibility-weighted angiography of the substantia nigra in diagnosing Parkinson disease. AJNR Am J Neuroradiol 36, 461–466 (2015).</li><li>Li, S. et al. Synthetizing SWI from 3T to 7T by generative diffusion network for deep medullary veins visualization. Neuroimage 320, 121475 (2025).</li><li>Lv, J. et al. Transfer learning enhanced generative adversarial networks for multi-channel MRI reconstruction. Comput Biol Med 134, 104504 (2021).</li><li>Qu, L., Zhang, Y., Wang, S., Yap, P.-T. &amp; Shen, D. Synthesized 7T MRI from 3T MRI via deep learning in spatial and wavelet domains. Med Image Anal 62, 101663 (2020).</li><li>Duan, C. et al. Synthesized 7T MPRAGE From 3T MPRAGE Using Generative Adversarial Network and Validation in Clinical Brain Imaging: A Feasibility Study. J Magn Reson Imaging 59, 1620–1629 (2024).</li><li>Eidex, Z. et al. High-resolution 3T to 7T ADC map synthesis with a hybrid CNN-transformer model. Med Phys51, 4380–4388 (2024).</li><li>Bahrami, K., Rekik, I., Shi, F. &amp; Shen, D. Joint Reconstruction and Segmentation of 7T-like MR Images from 3T MRI Based on Cascaded Convolutional Neural Networks. Med Image Comput Comput Assist Interv 10433, 764–772 (2017).</li><li>Sun, Y., Wang, L., Li, G., Lin, W. &amp; Wang, L. A foundation model for enhancing magnetic resonance images and downstream segmentation, registration and diagnostic tasks. Nat Biomed Eng 9, 521–538 (2025).</li><li>Billot, B. et al. SynthSeg: Segmentation of brain MRI scans of any contrast and resolution without retraining[J]. Medical image analysis, 86: 102789(2023).</li></ol><div style="margin:24px 0;"><img src="'+o+'" alt="Consortium logos" style="display:block;max-width:60%;height:auto;margin:0 auto;"></div>',22)])])}const u=a(r,[["render",l]]);export{p as __pageData,u as default};
